import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const projectDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sources = [
  "baseline-ui.css",
  "release-ui.css",
];

const banner = [
  "/* SOUS unified UI stylesheet.",
  " * Generated by scripts/build-styles.mjs.",
  " * Edit source styles, then run npm run build:styles.",
  " */",
  "",
].join("\n");

const body = sources
  .map((file) => {
    const source = fs.readFileSync(path.join(projectDir, file), "utf8").trim();
    return `/* ===== ${file} ===== */\n${source}\n`;
  })
  .join("\n");

fs.writeFileSync(path.join(projectDir, "sous-ui.css"), `${banner}${body}`, "utf8");
console.log(`Built sous-ui.css from ${sources.length} controlled style layers.`);
